---
-- Binary codec for fixed C struct layouts. Calling the module on a layout
-- descriptor (as generated by autogen, e.g.
-- `require("linux.netlink").layout.nlmsghdr`) derives a `string.pack` format
-- once and returns a codec exposing `pack`/`unpack`/`size`, so callers never
-- hand-write the byte layout. A codec also reads a struct where it lies, a field
-- at a time and by name, through a view over a `data` object.
-- @module struct
-- @usage
-- local struct = require("struct")
-- local nlmsghdr = struct(require("linux.netlink").layout.nlmsghdr)
-- local bytes = nlmsghdr:pack(len, mtype, flags, seq, pid)
-- local len, mtype = nlmsghdr:unpack(bytes)

local insert, concat, move, sort = table.insert, table.concat, table.move, table.sort
local pack, unpack, packsize     = string.pack, string.unpack, string.packsize

local struct = {}
struct.__index = struct

-- the data object's read of each width, unsigned and signed; a Lua integer is signed, so 8 bytes
-- read as getint64 either way
local unsigned = {[1] = "getuint8", [2] = "getuint16", [4] = "getuint32", [8] = "getint64"}
local signed   = {[1] = "getint8", [2] = "getint16", [4] = "getint32", [8] = "getint64"}

-- what each view reads from, kept outside it so that a struct may have a field of any name
local states = setmetatable({}, {__mode = "k"})

local view = {}

function view.__index(proxy, name)
	local state = states[proxy]
	local field = state.codec.readers[name]
	return state.data[field.getter](state.data, state.at + field.offset)
end

-- a write would land in the proxy, which every later read of that name would then answer
function view.__newindex()
	error("struct: a view is read-only", 2)
end

-- Derive the `string.pack` format from a layout: each field as `I<size>` (or
-- `i<size>` when signed), with `x` filling inter-field padding and the tail
-- up to `size`. Native byte order (`=`) for the host-endian struct. Returns
-- the format and the fields in the offset order it packs them.
local function build_format(layout)
	local fields = move(layout.fields, 1, #layout.fields, 1, {})
	sort(fields, function(a, b) return a.offset < b.offset end)
	local out, pos = {"="}, 0
	for _, f in ipairs(fields) do
		if f.offset > pos then insert(out, ("x"):rep(f.offset - pos)) end
		insert(out, (f.signed and "i" or "I") .. f.size)
		pos = f.offset + f.size
	end
	if layout.size > pos then insert(out, ("x"):rep(layout.size - pos)) end
	return concat(out), fields
end

-- each field's read, by its name: the data object's getter of its width and sign, at its offset
local function readers(layout)
	local byname = {}
	for _, field in ipairs(layout.fields) do
		byname[field.name] = {offset = field.offset, getter = (field.signed and signed or unsigned)[field.size]}
	end
	return byname
end

---
-- Codec a layout builds, packing its fields in native byte order. Its `size` field holds the
-- struct's size in bytes, and its `fields` field the layout's fields in offset order, the order
-- `pack` takes and `unpack` returns their values.
-- @type codec

---
-- Serializes the field values (in offset order) into the struct's bytes.
-- @function codec:pack
-- @param ... the field values
-- @treturn string
function struct:pack(...)
	return pack(self.format, ...)
end

---
-- Deserializes the struct's fields from a buffer.
-- @function codec:unpack
-- @tparam string buf
-- @tparam[opt] integer pos starting offset (1-based)
-- @return the field values in offset order, then the position past the struct
function struct:unpack(buf, pos)
	return unpack(self.format, buf, pos)
end

---
-- Returns the size in bytes of a named field.
-- @function codec:fieldsize
-- @tparam string name the field name.
-- @treturn integer|nil the field size, or `nil` if the layout has no such field.
function struct:fieldsize(name)
	for _, field in ipairs(self.layout.fields) do
		if field.name == name then return field.size end
	end
end

---
-- A view of the struct as it lies in `data` from `at`, which reads a field by its name:
-- `view.ttl` reads the field at `at` plus its offset, with its width and sign, each time it is
-- indexed, as the `data` object's reads do, so the bytes are in the kernel's byte order and a read
-- past the end of `data` raises as theirs does. A field is 1, 2, 4 or 8 bytes wide, and a name the
-- layout lacks raises.
-- @function codec:view
-- @tparam data data the bytes, a `data` object or one that reads as it does
-- @tparam integer at the offset in `data` the struct starts at
-- @treturn table the view
-- @raise "struct: a view is read-only", on an assignment to a field
-- @usage
-- local iphdr = struct(layout)
-- local ip = iphdr:view(packet, 14)
-- if ip.protocol == 17 then ... end
function struct:view(data, at)
	local proxy = setmetatable({}, view)
	states[proxy] = {codec = self, data = data, at = at}
	return proxy
end

---
-- Builds a codec from a layout descriptor.
-- @function struct
-- @tparam table layout `{ size = bytes, fields = { {name, offset, size, signed}, ... } }`
-- @treturn codec a codec exposing `:pack`, `:unpack`, `:fieldsize`, `:view` and the `size` and `fields`
--   fields.
-- @raise "struct: derived format does not match the layout size (overlapping fields?)"
-- @within struct
return function(layout)
	local format, fields = build_format(layout)
	assert(packsize(format) == layout.size,
		"struct: derived format does not match the layout size (overlapping fields?)")
	return setmetatable({format = format, size = layout.size, layout = layout, fields = fields,
		readers = readers(layout)}, struct)
end

